'use strict';
const TOOL='https://seedcoop.github.io/uridongne-player/';
const KEY='uridongne-mentor-guide:20261015:v1';
const weeks=[{"n":1,"short":"발견","title":"우리동네와 게임","tagline":"각자의 아이디어에서, 함께 만들 대표 기획으로.","goal":"각자 동네 경험을 바탕으로 한 장 기획서를 작성한다. 팀 회의에서 모두 발표한 뒤 투표로 대표 아이디어를 정한다.","out":"개별 기획서 + 팀 대표 기획·투표 기록","materials":["큰 종이·포스트잇","펜·색연필","기획서 웹도구","멘토가 일상 경험을 주제로 직접 만든 게임","투표 스티커 또는 빈 종이"],"decision":"각자 만들 게임의 행동·목표·이유, 투표로 선정할 팀 대표 아이디어.","question":"“내 게임에서 무엇을 해보고 싶나요? 우리 팀은 어떤 아이디어를 함께 만들까요?”","mentor":"개별 기획서를 먼저 갖추게 돕고, 팀 회의에서 모두 발표한 뒤 투표하도록 진행한다. 대표 아이디어를 대신 정하지 않는다.","open":"1주차 기획서 도구로 각자 기획을 정리해 MD·PDF로 저장하고, 타이틀 커버 요청문으로 가상의 게임 커버 이미지를 생성합니다. 팀 회의와 투표 뒤 선정된 대표 기획을 팀 기록으로 보관합니다.","defer":"개별 작성 중 대표를 미리 정하는 일, 게임 코드·실제 게임 자산 제작.","links":[],"minimum":"큰 종이·포스트잇에 직접 펼친 개인 마인드맵, 개별 기획 파일, 투표 결과와 선정 이유, 팀 대표 기획 파일 1개.","stuck":[["개별 기획서가 잘 안 나오면?","장소와 그곳에서 있었던 일부터 말이나 그림으로 남기고, 플레이어가 할 행동 하나를 질문합니다. 친구의 기획을 대신 쓰게 하지 않습니다."],["투표 결과가 같으면?","동률 후보의 핵심 행동과 함께 만들고 싶은 이유를 다시 듣고 해당 후보만 재투표합니다. 선정되지 않은 개인 기획서도 보관합니다."]]},{"n":2,"short":"기획","title":"무드보드와 게임 타이틀","tagline":"우리 게임의 분위기를, 첫인상으로.","goal":"대표 기획의 분위기·색·시각 방향을 무드보드로 정한다. 이어서 게임 제목·로고·대표 상징을 담은 타이틀을 만들고 선택 이유를 설명한다.","out":"시각 무드보드 PNG·JSON + 게임 타이틀 이미지·선택 기록","materials":["지난주 대표 기획","시각 무드보드 웹도구 또는 빈 PPT·PDF 양식","출처와 함께 준비한 이미지 후보 6~9개","타이틀 제작에 사용할 이미지 기능 또는 빈 종이·펜"],"decision":"대표색·분위기·피할 표현, 타이틀에 넣을 게임 제목·로고·대표 상징과 배치.","question":"“무드보드의 어떤 느낌을 우리 게임의 제목과 타이틀에서 보여주고 싶어?”","mentor":"무드보드의 선택이 타이틀의 색·글자·상징에 어떻게 이어졌는지 묻는다. 제목이 읽히는지 함께 확인하고 최종 선택과 이유는 청소년이 정하도록 돕는다.","open":"20~55분: 제목·색·임시 상징·참고 그림과 이유·출처·피할 표현을 모아 시각 무드보드를 만듭니다. 60~100분: 그 무드보드를 확인하며 2주차 도구로 게임 타이틀 요청문을 만들고, 제목·로고·대표 상징을 담은 타이틀을 제작·비교·선택합니다.","defer":"캐릭터·배경·아이템 등 플레이용 이미지 애셋 제작은 3주차로 넘깁니다. 게임 코드·애니메이션·배경 음악과 전체 화면 제작도 이후에 진행합니다.","links":[3,7],"minimum":"대표 색 3~6개, 임시 상징 1개, 참고 그림 3개와 이유·출처, 피할 표현 3~5개를 담은 무드보드 PNG·수정용 JSON. 이어서 게임 제목이 읽히는 타이틀 이미지 또는 직접 만든 타이틀 시안 1개와 선택 이유·출처를 저장합니다.","stuck":[["“다 좋아요”라고만 하면?","두 무드보드 후보나 타이틀 시안에서 다른 점 하나를 찾고, “우리 게임 분위기와 더 맞는 쪽은?”처럼 비교 기준 하나를 정한다."],["타이틀의 제목이 잘 안 읽히면?","게임 제목의 정확한 글자를 먼저 확인하고 글자 크기·대비·배치 중 한 가지만 고친다. 이미지 기능이 글자를 잘못 만들면 종이·도형·텍스트로 직접 조합한 타이틀을 남긴다."],["캐릭터나 배경도 만들고 싶어 하면?","만들고 싶은 이미지와 이유를 3주차 애셋 목록에 기록하고, 오늘은 무드보드와 게임 타이틀을 마무리한다."]]},{"n":3,"short":"구현","title":"이미지 애셋과 게임 프로토타입","tagline":"작은 행동 하나가, 다시 하고 싶은 놀이로.","goal":"지난주 무드보드와 게임 타이틀을 확인해 플레이에 필요한 이미지 애셋 한 가지를 만든다. 행동 → 상태 변화 → 피드백 → 다음 행동을 연결해 한 판을 시작하고 끝내고 다시 할 수 있게 한다.","out":"이미지 애셋 1개·선택 기록 + 핵심 행동이 작동하는 v0.1·테스트 메모","materials":["대표 기획·무드보드 PNG·게임 타이틀","주차별 도구 기록","이미지 기능 또는 직접 그림·도형 도구","Codex 작업 폴더","주차별 게임·이미지 백업 폴더"],"decision":"이번에 만들 캐릭터·배경·아이템 중 한 가지와 유지할 표현, 핵심 행동·조작·한 판의 완료 조건.","question":"“무드보드의 어떤 특징을 이 이미지에 남길까? 그 이미지로 어떤 행동을 해볼까?”","mentor":"이미지 제작 전 무드보드와 타이틀을 함께 열고 일관된 색·모양·분위기를 확인한다. 청소년이 애셋을 고른 이유와 규칙을 설명하게 돕고, 그림 제작이 지연되면 임시 도형으로 핵심 놀이를 먼저 실행한다.","open":"10~35분: 3주차 도구의 ‘이미지 애셋 요청’으로 무드보드에 맞는 캐릭터·배경·아이템 중 한 가지를 제작·선택합니다. 35~60분: 종이로 핵심 규칙을 시험하고 ‘게임 구현 요청’으로 행동·조작·완료를 정리합니다. 휴식 뒤 Codex에서 작은 한 판을 구현·실행합니다.","defer":"모든 이미지 애셋 완성, 새 레벨·온라인 기능·풍부한 사운드·애니메이션. 오늘 이미지는 한 가지만 만들고, 세부 화면 적용과 표현 보완은 4주차에 이어갑니다.","links":[4,5],"minimum":"무드보드를 확인해 고른 플레이용 이미지 애셋 1개 또는 직접 그림·도형 시안, 선택 이유·출처. 시작 → 핵심 행동 → 성공/종료 → 다시 하기가 되는 v0.1과 바뀐 점·남은 문제 각 1개. 이미지 적용이 막히면 임시 도형으로 실행본을 보관합니다.","stuck":[["이미지 제작이 지연되면?","무드보드에서 가져올 색·모양과 만들 대상 한 가지를 남기고 직접 그림이나 임시 도형으로 진행한다. 이미지 완성 때문에 핵심 놀이 구현을 멈추지 않는다."],["AI가 기능을 너무 많이 만들면?","3주차 도구에 오늘 구현할 행동·규칙·완료만 남기고 ‘게임 구현 요청’을 사용한다. 새 애셋이나 기능은 한 번에 하나로 좁힌다."],["동작하지 않으면?","마지막으로 작동한 버전으로 돌아간다. 어떤 화면에서 어떤 조작을 했는지, 예상과 실제가 어떻게 달랐는지 적어 Codex에 요청한다."]]},{"n":4,"short":"표현","title":"게임 화면 구성하기","tagline":"처음 온 친구도 혼자 놀 수 있게.","goal":"정한 분위기를 게임 화면에 반영하고 조작·목표·결과를 알아보기 쉽게 만든다. 핵심 규칙을 유지하며 한 가지씩 개선한다.","out":"표현을 반영한 v0.2 + 변경 전후 기록","materials":["v0.1 백업","무드보드·핵심 이미지","자유롭게 스케치할 빈 종이·펜","변경 기록"],"decision":"꼭 남길 색과 이미지, 처음 하는 친구를 위한 안내 문장, 우선 개선할 화면.","question":"“처음 보는 친구가 지금 무엇을 해야 하는지 알 수 있을까?”","mentor":"“더 예쁘게”를 구체적인 요청으로 바꾼다. 예: “남은 물건 수를 위쪽에 크게”. 바꾼 뒤에도 핵심 행동과 다시 하기를 확인한다.","open":"4주차 도구에 바꿀 화면 한 부분·원하는 변화·그대로 둘 규칙을 적고 수정 요청문을 만듭니다. 먼저 v0.1이 실행되는지 확인하고, 실행되지 않으면 정상본 복구를 우선합니다.","defer":"기획 전면 교체, 장식 효과 한꺼번에 추가, 새로운 규칙. 사운드는 필요한 반응부터 선택하며 없어도 괜찮다.","links":[6,7],"minimum":"시작·플레이·결과 화면과 조작 안내가 보이는 v0.2. 변경 전후 한 쌍과 선택 이유 1문장.","stuck":[["v0.1이 아직 실행되지 않으면?","초반 25분에 직전 정상본이나 임시 도형 버전으로 복구합니다. 복구하면 안내 한 가지만 개선하고, 계속 막히면 65~90분 구현 시간을 핵심 루프 복구에 쓰며 새 그림·배경 적용을 미룹니다."],["어디부터 꾸밀지 못 고르면?","플레이어·목표물·안내 중 가장 알아보기 어려운 하나를 고른다. 이번 수정의 완료 조건을 먼저 말한다."],["이미지 넣은 뒤 게임이 멈추면?","임시 도형 버전으로 되돌려 작동을 지킨다. 경로·파일명을 확인하고 이미지 하나만 다시 적용한다."]]},{"n":5,"short":"검증","title":"게임 테스트와 완성","tagline":"오류를 찾는 일도, 게임을 만드는 일.","goal":"설명을 보태지 않고 다른 팀의 플레이를 관찰한다. 오류와 취향을 구분하고 반드시 고칠 문제부터 수정한다.","out":"통과 포함 테스트 기록 + 수정·재확인한 v0.3","materials":["v0.2 실행본","5주차 QA 웹도구","자유 메모용 빈 종이·포스트잇·펜","작동 버전 백업"],"decision":"가장 먼저 고칠 문제와 이번 버전에 남길 재미.","question":"“언제, 무엇을 했을 때, 예상과 다르게 어떤 일이 일어났어?”","mentor":"“재미없어요”는 취향 의견일 수 있다. “다시 하기를 눌렀는데 점수가 남아요”처럼 다시 확인할 수 있는 관찰로 바꾸도록 돕는다.","open":"5주차 도구에서 테스트 결과를 ‘통과·문제 발견·미확인’으로 구분하고 예상·실제·순서를 적습니다. 통과 기록은 저장하고, 문제를 발견한 경우에만 수정 요청문을 사용합니다.","defer":"QA 중 새 기능 확장, 모든 취향 의견 반영, 재검사 없이 해결 표시. 최소 완성 범위를 지킨다.","links":[8],"minimum":"통과를 포함한 테스트 기록 3건, 발견한 문제의 우선순위·수정 후 확인, 재검사한 v0.3. 한 건마다 TXT로 저장한 뒤 다음 기록을 적습니다.","stuck":[["문제를 너무 많이 발견하면?","플레이를 막는 것, 규칙이 틀리는 것, 읽기 어려운 것 순서로 한 건을 고른다. 다음 버전 항목은 따로 남긴다."],["고쳤는데 다른 곳이 깨지면?","마지막 작동 버전으로 돌아가 변경을 더 작게 나눈다. 시작부터 다시 하기까지 한 판을 재검사한다."]]},{"n":6,"short":"공유","title":"배포하고 설명하기","tagline":"게임과 함께, 우리가 고른 이유를 전하기.","goal":"운영진이 정한 방식으로 실행본을 준비한다. 청소년이 동네 경험·핵심 규칙·수정한 이유를 자기 말로 소개한다.","out":"최종 실행본 + 3분 소개·플레이 시연 + 제작 기록","materials":["v0.3·최종 후보","최종 QA 기록","이미지·소리 출처","발표 메모·실행 안내"],"decision":"게임 소개 문장, 팀이 가장 자랑하고 싶은 변화, 다음 버전에 남길 아이디어.","question":"“이 게임에 우리 동네와 우리 팀의 생각이 어디에 남아 있어?”","mentor":"발표의 중심을 제작자가 차지하게 한다. 멘토는 실행과 자료 정리를 지원하고, 선택과 수정의 이유는 청소년이 말하게 한다.","open":"6주차 도구에서 작품 소개·조작·우리 팀의 선택·개선 경험·출처를 정리합니다. 대표 이미지는 게임 화면이나 별도 파일과 함께 보여주고, 1분 소개와 2분 플레이·마무리를 연습합니다.","defer":"발표 직전 새 기능, 최종본 위에서 실험, 확인 전 임의 공개. 제출처·기한·공개 범위는 운영진 확인.","links":[8],"minimum":"다른 기기에서 확인한 최종 실행본, 실행 안내·자산 출처·제작 기록, 소개 1분 + 플레이·마무리 2분으로 구성한 3분 시연.","stuck":[["인터넷이 되지 않으면?","사전에 확인한 로컬 실행본을 사용한다. 설치가 필요한 프로젝트는 실행 안내를 함께 준비하고, 대안으로 플레이 녹화와 화면을 둔다."],["발표가 어려우면?","“우리 동네의 ○○에서 시작했어요 / ○○하면 ○○해요 / 친구 의견을 듣고 ○○를 바꿨어요” 세 문장으로 짝 리허설한다."]]}];
const weeklyTimeline=[{"week":1,"title":"우리동네와 게임","date":"2026-11-06","blocks":[{"duration":5,"title":"서로 만나고, 오늘 할 일 열기","summary":"오늘은 각자 기획서를 만든 뒤 팀 회의와 투표로 대표 아이디어를 정합니다.","steps":["서로 부를 이름을 정하고 한 번씩 인사합니다.","개별 기획 → 팀 안에서 발표 → 투표 → 대표 기획 정리 순서를 안내합니다."],"question":"내가 게임으로 만들어 보고 싶은 동네 이야기는 무엇인가요?","materials":["이름표 또는 메모지"],"tools":[],"output":"서로 부를 이름과 오늘 활동 순서","nextCriterion":"각자 자기 기획을 먼저 만든다는 순서를 이해하면 다음 활동으로 갑니다.","start":0,"end":5,"elapsed":"0~5분"},{"duration":15,"title":"우리동네 진진가로 이야기 듣기","summary":"멘토가 동네·일상 사례로 진진가를 먼저 보여주고, 가짜를 맞히며 구성원들의 경험 이야기를 엽니다.","steps":["멘토가 자신의 동네·일상 경험으로 만든 진짜 이야기 두 개와 가짜 한 개를 먼저 들려줍니다.","구성원들이 가짜라고 생각한 이야기를 고르고 이유를 말하면, 멘토가 정답과 실제 경험을 밝힙니다.","시연을 본 구성원들도 자기 동네·일상 경험으로 진진가에 참여하도록 권합니다. 게임 소재가 될 만한 경험 한 가지를 기억해 다음 마인드맵에 이어갑니다."],"question":"내 이야기 중 게임으로 바꾸면 재미있을 장면은 무엇인가요?","materials":["멘토가 준비한 동네·일상 진진가 사례","필요하면 자유 메모용 빈 종이·펜"],"tools":[],"output":"각자의 동네 경험 후보","nextCriterion":"모두 한 번씩 말하거나 그림으로 소개하면 넘어갑니다.","start":5,"end":20,"elapsed":"5~20분"},{"duration":20,"title":"내 동네 이야기 떠올리기 · 마인드맵","summary":"진진가에서 나눈 우리 동네 경험을 가운데 ‘우리 동네’와 네 가지 키워드로 이어 펼칩니다.","steps":["멘토가 화면이나 보드에 가운데 ‘우리 동네’와 네 가지 키워드 ‘자주 가는 곳·만나는 사람·기억나는 일·좋아하는 놀이’를 미리 보여줍니다. 진진가에서 나눈 경험을 떠올리며 함께 읽고, ‘놀이터 → 비 온 뒤 물웅덩이 → 폴짝 뛰다’처럼 경험 하나를 시연합니다.","청소년이 큰 종이에 중심과 가지를 직접 그리거나 포스트잇을 붙이고, 떠오르는 가지부터 낱말·그림을 2개 이상 남깁니다. 네 가지를 모두 채울 필요는 없습니다. 쓰기 어려우면 말로 설명하고 멘토가 짧게 받아 적습니다.","짝에게 한 장면을 들려주고 “그때 무슨 일이 있었어?”, “그때 내가 한 행동은?”을 묻습니다. 생각난 사건이나 행동을 마인드맵에 덧붙입니다.","게임으로 만들고 싶은 소재 하나에 별표를 하고, 옆에 행동 낱말 하나를 남깁니다. 잠시 뒤 멘토의 게임을 직접 해보고, 내 소재를 개별 웹 기획서로 옮깁니다."],"question":"별표 한 장면에서, 나는 무엇을 했나요? 게임에서는 무엇을 해보고 싶나요?","materials":["큰 종이","포스트잇","펜·색연필"],"tools":["중앙 ‘우리 동네’와 네 키워드를 보여줄 공유 화면 또는 보드"],"output":"개인 마인드맵: 낱말·그림 2개 이상 + 별표 소재 하나 + 행동 낱말 하나","nextCriterion":"각자의 별표 소재를 개별 한 장 기획서에 이어 씁니다.","start":20,"end":40,"elapsed":"20~40분"},{"duration":15,"title":"멘토의 일상으로 만든 게임 플레이하기","summary":"멘토가 자신의 경험으로 만든 게임을 소개하면, 청소년이 번갈아 직접 조작해 한 판씩 체험합니다.","steps":["멘토가 직접 겪은 일상 경험과 그 경험으로 만든 게임을 짧게 소개합니다.","청소년이 번갈아 직접 게임을 조작해 한 판을 체험한 뒤, 직접 한 행동과 무엇을 해내면 끝났는지 말합니다.","멘토의 경험이 게임의 행동·목표로 바뀐 모습을 짚고, 내 마인드맵의 별표 소재에서는 어떤 행동을 해볼지 연결합니다."],"question":"멘토의 일상 경험이 게임에서 어떤 행동과 목표가 되었나요? 내 별표 소재는 어떤 놀이가 될까요?","materials":["멘토가 일상 경험을 주제로 직접 만든 게임","개인 마인드맵"],"tools":["멘토 게임 실행본 또는 링크"],"output":"멘토 게임의 행동·목표와 내 소재에서 해보고 싶은 행동 한 가지","nextCriterion":"경험이 게임의 행동과 목표로 이어지는 모습을 확인한 뒤 개별 기획서로 정리합니다.","start":40,"end":55,"elapsed":"40~55분"},{"duration":5,"title":"잠깐 쉬기","summary":"개인 메모를 남겨두고 다음 기획서 작업을 준비합니다.","steps":["작성 중인 메모와 화면을 그대로 남깁니다.","5분 뒤 같은 자리로 돌아옵니다."],"question":"돌아오면 어떤 경험을 기획서로 정리할까요?","materials":["개인 마인드맵"],"tools":[],"output":"이어서 쓸 수 있는 개인 마인드맵","nextCriterion":"5분 휴식 뒤 개별 기획서 작성으로 이어갑니다.","start":55,"end":60,"elapsed":"55~60분"},{"duration":20,"title":"개별 한 장 기획서 만들기","summary":"웹도구로 각자의 마인드맵에서 고른 소재를 한 장 기획서로 정리합니다.","steps":["1주차 웹도구를 열고 마인드맵의 별표 소재와 행동 낱말을 보며 장소·경험·핵심 행동·목표·고른 이유를 각자 적습니다.","멘토는 빈칸을 대신 채우기보다 한 장면의 놀이로 설명이 되는지 질문합니다.","발표할 제목·행동·목표·이유를 표시하고 개인 기획서를 MD 또는 PDF로 저장합니다.","기획 도구의 ‘타이틀 커버’ 요청문을 Codex에 전달해, 내 기획으로 만든 가상의 게임 타이틀 커버 이미지를 생성합니다. 게임 이름과 내가 고른 소재가 드러나는지 확인합니다."],"question":"내 게임에서 플레이어는 무엇을 하고, 무엇을 해내면 한 판이 끝나나요?","materials":["개인 마인드맵","기획서를 작성할 기기"],"tools":["1주차 아이디어 한 장 기획서 도구"],"output":"청소년 각자의 한 장 기획서 MD·PDF + 가상의 게임 타이틀 커버 이미지","nextCriterion":"모두 자신의 기획서를 갖추면 팀 회의로 넘어갑니다. 대표 아이디어는 아직 정하지 않습니다.","start":60,"end":80,"elapsed":"60~80분"},{"duration":30,"title":"기획 발표·투표로 대표 아이디어 정하기","summary":"모두의 기획을 듣고 후보를 비교한 뒤, 한 사람 한 표로 대표 아이디어와 선정 이유를 정합니다.","steps":["한 사람씩 기획 화면을 보며 제목·동네 경험·핵심 행동·목표·고른 이유를 발표합니다. 다른 구성원은 궁금한 점을 묻고, 모든 후보를 들은 뒤 선택합니다.","후보의 제목과 핵심 행동을 공유 화면이나 보드·포스트잇에 모아 비교하고, 함께 만들고 싶은 기준을 확인한 뒤 한 사람 한 표로 투표합니다.","득표를 함께 확인합니다. 동률이면 해당 후보의 핵심 행동과 함께 만들고 싶은 이유를 다시 듣고, 동률 후보만 재투표합니다.","선정 기획의 행동·목표·팀의 선정 이유를 웹 도구에 저장하고, 투표 결과는 웹 기록이나 자유 메모로 남깁니다. 다른 개인 기획 파일도 보관합니다."],"question":"모두의 기획을 들어 보니, 우리 팀은 어떤 아이디어를 왜 함께 만들고 싶나요?","materials":["각자의 기획 파일","후보 제목·핵심 행동 메모","투표 스티커 또는 빈 종이"],"tools":["개별 기획 파일을 보여줄 공유 화면","1주차 기획서 도구","공유 화면 또는 보드·자유 메모"],"output":"모두의 발표·비교·투표 결과와 선정 이유, 팀 대표 기획 파일","nextCriterion":"모두의 발표를 듣고 득표와 선정 이유를 확인한 뒤, 대표 기획을 다음 주에 이어 쓸 상태로 저장합니다.","start":80,"end":110,"elapsed":"80~110분","note":"※ 팀을 나누고 싶다는 그룹이 나올 경우에만 팀을 나눕니다. 멘토가 먼저 팀 나누기를 독려하지 않습니다."},{"duration":10,"title":"대표 아이디어 공유와 다음 주 준비","summary":"개인 기획과 투표 결과를 보관하고 다음 주 표현 활동을 예고합니다.","steps":["팀 대표 기획을 한 문장으로 소개하고 선정 이유를 말합니다.","개인 기획서, 투표 기록, 대표 기획을 구분해 저장합니다. 다음 주에는 선정된 대표 기획을 엽니다.","대표 게임에 어울리는 제목·색·주인공을 다음 주에 정한다고 안내합니다."],"question":"다음 주에는 우리 대표 게임을 어떤 모습으로 보여주고 싶나요?","materials":["개인 기획서","투표 기록","팀 대표 기획서"],"tools":["MD·PDF·TXT 저장 또는 도구 JSON 백업"],"output":"개인 기획서 모음·대표 기획·투표 기록","nextCriterion":"모든 개인 기획과 대표 기획의 저장 위치를 확인하면 마칩니다.","start":110,"end":120,"elapsed":"110~120분"}]},{"week":2,"title":"무드보드와 게임 타이틀","date":"2026-11-13","blocks":[{"start":0,"end":20,"duration":20,"elapsed":"0~20분","title":"지난 결정 복기·AI 결과 비교","summary":"지난주 대표 기획을 다시 보고, AI 결과도 우리 기준으로 고릅니다.","steps":["W01 대표 기획과 직접 만든 마인드맵·사진을 열고 핵심 행동·목표·꼭 남길 것을 확인합니다.","같은 소재의 이미지나 손그림 두 안에서 우리 이야기와 맞는 부분·다른 부분을 말합니다.","AI는 후보를 제안하고 마지막 선택은 팀이 한다는 원칙을 확인합니다."],"question":"어느 부분이 우리 이야기 같고, 무엇은 바꾸고 싶나요?","materials":["W01 대표 기획·마인드맵 또는 사진","비교할 이미지 또는 손그림 2안"],"tools":["1주차 기획 기록","준비된 이미지 또는 사용 가능한 이미지 기능"],"output":"그대로 둘 이야기와 오늘 정할 표현·비교 기준","nextCriterion":"지난주 결정과 오늘 표현을 고를 기준을 확인하면 무드보드로 갑니다."},{"start":20,"end":55,"duration":35,"elapsed":"20~55분","title":"제목·색·상징·시각 무드보드","summary":"그림과 색을 직접 모아 한 장의 시각 방향을 만듭니다.","steps":["활동 0~5분: 대표 기획을 보고 팀 이름과 게임의 임시 이름을 적습니다.","활동 5~10분: 대표 색 3~6개를 고르고 어울리는 느낌을 말합니다.","활동 10~15분: 준비 그림·스케치·도형으로 임시 상징 한 장을 넣습니다.","활동 15~27분: 참고 그림 세 장을 넣고, 그림마다 고른 이유와 출처를 짧게 적습니다.","활동 27~32분: 피하고 싶은 표현 3~5개를 적고 팀의 선택 이유를 설명합니다.","활동 32~35분: PNG와 JSON을 저장하고 다시 열어 확인합니다."],"question":"이 색·상징·그림이 우리가 고른 경험에 왜 어울리나요?","materials":["팀 대표 기획","멘토가 출처와 함께 준비한 이미지 후보 6~9개","직접 스케치할 종이·펜"],"tools":["시각 무드보드 웹도구","빈 무드보드 PPT·PDF 양식"],"output":"제목·색 3~6개·임시 상징·참고 그림 3개와 이유·출처·피할 표현 3~5개가 담긴 시각 무드보드 PNG와 JSON","nextCriterion":"전원의 후보를 듣고 팀이 선택 이유를 설명하며 PNG·JSON을 저장하면 휴식합니다. 무드보드의 방향을 다음 게임 타이틀 만들기에 이어 씁니다."},{"start":55,"end":60,"duration":5,"elapsed":"55~60분","title":"휴식","summary":"시각 무드보드를 저장해 두고 잠깐 쉬어갑니다.","steps":["무드보드 PNG와 JSON이 팀 폴더에 있는지 확인합니다.","5분 뒤 팀 자리로 돌아옵니다."],"question":"돌아오면 무드보드의 어떤 색·분위기를 게임 타이틀에 담을까요?","materials":["시각 무드보드 PNG·JSON"],"tools":[],"output":"다시 열 수 있는 무드보드","nextCriterion":"5분 휴식 뒤 게임 타이틀 만들기로 이어갑니다."},{"start":60,"end":100,"duration":40,"elapsed":"60~100분","title":"게임 타이틀 만들기","summary":"완성한 무드보드의 색·분위기를 제목·로고·대표 상징이 보이는 게임 타이틀로 이어갑니다.","steps":["무드보드 PNG를 열고 대표 색·시각 방향·피할 표현을 확인합니다. 타이틀에 쓸 게임 제목의 정확한 글자를 정합니다.","2주차 도구의 ‘무드보드 선택 이어받기’로 빈칸을 채우고, 제목 글자·로고·대표 상징의 배치와 꼭 남길 특징을 적습니다.","타이틀 요청문과 무드보드 PNG를 함께 전달해 타이틀 시안을 만듭니다. 이미지 기능이 없거나 지연되면 종이·도형·텍스트로 직접 조합합니다.","시안 1~2개를 비교해 제목이 읽히는지, 우리 게임의 분위기가 보이는지 이야기하고 한 안을 고릅니다.","글자·색·배치 중 꼭 필요한 한 부분만 다듬고 타이틀 원본·출처·선택 이유를 기록합니다. 캐릭터·배경·아이템 애셋은 3주차 목록에 남깁니다."],"question":"무드보드에서 정한 분위기가 타이틀의 어느 색·글자·상징에 보이나요?","materials":["무드보드 PNG·JSON","정확한 게임 제목","타이틀 시안","빈 종이·펜 또는 도형·텍스트 도구"],"tools":["2주차 게임 타이틀 요청 도구","사용 가능한 이미지 기능 또는 직접 타이틀 조합"],"output":"게임 타이틀 요청문·채택 타이틀 이미지 또는 직접 만든 시안·출처·선택 이유","nextCriterion":"제목이 읽히고 무드보드와 타이틀의 방향이 맞으며 팀이 선택 이유를 설명하면 저장·공유로 갑니다."},{"start":100,"end":120,"duration":20,"elapsed":"100~120분","title":"타이틀 소개·기획 기록·저장","summary":"무드보드가 게임 타이틀로 이어진 이유를 설명하고 다음 주 애셋 제작에 쓸 자료를 저장합니다.","steps":["팀원이 무드보드에서 고른 색·상징·분위기가 타이틀에 어떻게 반영됐는지 나누어 설명합니다.","게임 제목이나 시각 방향을 바꿨다면 무드보드와 2주차 도구 기록을 같은 내용으로 맞춥니다.","무드보드 PNG·수정용 JSON, 타이틀 원본, 선택 이유·출처, 주차별 도구 JSON을 구별해 팀 폴더에 저장합니다.","다음 주 만들 캐릭터·배경·아이템 이미지 중 우선할 한 가지와 핵심 행동을 기록합니다."],"question":"무드보드에서 타이틀로 이어진 우리 팀의 선택과 이유를 설명할 수 있나요?","materials":["무드보드","게임 타이틀 원본","선택 이유·출처 메모"],"tools":["무드보드 PNG·JSON 저장","2주차 게임 타이틀 기록·도구 JSON 백업"],"output":"무드보드 PNG·JSON, 게임 타이틀 원본·출처·선택 이유, 도구 기록, 3주차 이미지 애셋 후보","nextCriterion":"무드보드·타이틀 원본·도구 JSON을 구별해 저장하고 다음 주 이미지 애셋 제작 순서를 확인하면 마칩니다."}]},{"week":3,"title":"이미지 애셋과 게임 프로토타입","date":"2026-11-20","blocks":[{"start":0,"end":10,"duration":10,"elapsed":"0~10분","title":"무드보드·타이틀 복기와 역할 정하기","summary":"지난주 무드보드와 게임 타이틀을 열고 오늘 만들 이미지 한 가지와 역할을 정합니다.","steps":["W02 무드보드·게임 타이틀·대표 기획을 열어 꼭 남길 색·모양·분위기를 확인합니다.","캐릭터·배경·아이템 중 오늘 핵심 행동에 필요한 이미지 애셋 한 가지를 고릅니다.","기획·그림·구현 확인 역할을 나누되 모두 선택·발언·플레이에 참여합니다."],"question":"오늘 게임이 움직여도 꼭 그대로 남아야 할 우리 선택은 무엇인가요?","materials":["W02 무드보드 PNG·JSON","게임 타이틀·대표 기획"],"tools":["3주차 도구: 앞주 기록 이어받기"],"output":"오늘 만들 이미지 애셋 한 가지·역할·유지할 시각 방향","nextCriterion":"무드보드와 타이틀을 확인하고 이미지 대상 한 가지를 고르면 제작으로 갑니다."},{"start":10,"end":35,"duration":25,"elapsed":"10~35분","title":"무드보드 기반 이미지 애셋 만들기","summary":"무드보드의 방향으로 플레이에 필요한 이미지 한 가지를 제작·비교·선택합니다.","steps":["3주차 도구에서 앞주 기록을 이어받고, 이번에 만들 캐릭터·배경·아이템 중 한 가지와 꼭 남길 특징을 적습니다.","‘이미지 애셋 요청’ 탭의 요청문과 무드보드 PNG를 함께 전달합니다. 타이틀과 같은 색·그림 느낌·피할 표현을 먼저 확인하도록 요청합니다.","기능이 없거나 지연되면 직접 그림·도형을 후보로 만듭니다. 결과를 기다리는 동안 필요한 파일과 배치 위치를 정리합니다.","후보 1~2개를 비교해 무드보드와 어울리는지, 게임에서 알아보기 쉬운지 말하고 팀이 한 안을 고릅니다.","유지할 점 하나와 바꿀 점 하나만 정리하고 이미지 원본·파일명·출처·선택 이유를 보관합니다."],"question":"이 이미지의 어느 특징이 지난주 무드보드와 게임 타이틀에서 이어졌나요?","materials":["무드보드 PNG","게임 타이틀","이미지 후보 또는 빈 종이·펜·도형"],"tools":["3주차 도구: 이미지 애셋 요청","사용 가능한 이미지 기능 또는 직접 그림"],"output":"이미지 애셋 요청문·채택 이미지 1개 또는 직접 만든 시안·파일명·출처·선택 이유","nextCriterion":"이미지 한 가지의 방향과 선택 이유를 확인하고 저장하면 규칙 시험으로 갑니다. 제작이 지연되면 임시 도형을 씁니다."},{"start":35,"end":50,"duration":15,"elapsed":"35~50분","title":"핵심 루프와 규칙을 종이로 시험하기","summary":"행동 → 변화 → 피드백 → 다음 행동의 흐름과 한 판의 완료 조건을 확인합니다.","steps":["빈 종이·포스트잇에 길과 물건을 배치하고 핵심 행동·조작·규칙·완료 조건을 한 문장씩 정합니다.","한 명이 플레이어 행동을 하면 다른 친구가 변화와 눈에 보이는 반응을 표시하고 다음 행동으로 이어봅니다.","친구가 한 판을 해보며 다르게 이해한 곳을 말하고, 수치나 조건 하나만 조정해 다시 시험합니다."],"question":"행동 뒤 무엇이 바뀌고, 어떤 순간에 끝났다고 알려주면 될까요?","materials":["직접 만든 종이 배치안","빈 종이·포스트잇·펜"],"tools":["3주차 핵심 규칙 도구"],"output":"팀 게임의 루프·검토한 행동·조작·규칙·완료 조건","nextCriterion":"한 장면에서 실행 가능한 조건을 팀이 합의하면 넘어갑니다. 점수·실패·장애물은 필요할 때만 채택합니다."},{"start":50,"end":60,"duration":10,"elapsed":"50~60분","title":"게임 구현 요청과 이미지 파일 준비","summary":"확인한 규칙을 요청문으로 정리하고 채택 애셋 또는 임시 도형을 준비합니다.","steps":["3주차 도구의 ‘게임 구현 요청’에서 행동·규칙·완료·다시하기를 확인합니다. 무드보드와 게임 타이틀의 표현도 유지하도록 요청합니다.","팀 프로젝트와 이미지 파일명을 확인합니다. 단일 스타터라면 외부 의존성 없는 index.html을 유지합니다.","채택한 이미지 한 가지만 적용할 위치를 표시합니다. 준비되지 않은 이미지는 임시 도형으로 두고 표현 보완은 4주차로 남깁니다."],"question":"오늘 꼭 작동해야 할 것 하나와 다음 주로 남길 표현 하나는 무엇인가요?","materials":["무드보드·게임 타이틀","3주차 구현 요청문","채택 이미지 원본 또는 임시 도형"],"tools":["3주차 도구: 게임 구현 요청","Codex에 전달할 요청문·이미지 파일"],"output":"핵심 루프 구현 요청문·적용할 이미지 파일 또는 임시 도형","nextCriterion":"무드보드·타이틀·이미지의 방향과 구현할 핵심 규칙을 확인하면 휴식합니다."},{"start":60,"end":65,"duration":5,"elapsed":"60~65분","title":"요청과 파일을 남겨두고 쉬기","summary":"제작 요청을 반복해서 보내지 않고 잠깐 쉽니다.","steps":["오늘 요청과 원본 스타터 위치를 확인합니다.","5분 쉰 뒤 돌아옵니다."],"question":"돌아와서 첫 번째로 확인할 동작은 무엇인가요?","materials":["오늘 범위 요청문"],"tools":[],"output":"확정된 요청문","nextCriterion":"5분 휴식 뒤 제작 활동을 시작합니다."},{"start":65,"end":90,"duration":25,"elapsed":"65~90분","title":"Codex로 한 루프 구현하기","summary":"전체 게임을 한 번에 만들지 않고 확인된 범위부터 구현합니다.","steps":["멘토와 청소년이 오늘 요청을 읽고 Codex에 전달합니다.","구현을 기다리는 동안 청소년은 첫 행동과 예상 결과를 적고, 그림 담당은 채택 이미지 파일명·출처를 정리합니다.","실행 화면이 나오면 시작·핵심 행동·완료·다시하기 순서로 함께 해봅니다."],"question":"우리가 예상한 반응이 실제로 어느 순간에 나타났나요?","materials":["오늘 범위 요청문","예상 결과 메모"],"tools":["Codex","추가 실습용 index.html 또는 준비된 팀 프로젝트","브라우저"],"output":"한 번 실행해본 작은 프로토타입","nextCriterion":"핵심 행동과 완료·다시하기가 이어지면 넘어갑니다. 막히면 남은 시간 안에 정상 스타터로 돌아가 한 규칙만 반영합니다."},{"start":90,"end":105,"duration":15,"elapsed":"90~105분","title":"플레이하고 한 가지 바꿔 비교","summary":"각자가 해본 결과로 작은 변경을 고릅니다.","steps":["팀원이 번갈아 직접 플레이하고 예상과 다른 순간을 하나씩 말합니다.","속도·목표 수·배치·안내 중 이번에 바꿀 한 가지를 팀이 고릅니다.","메인 Codex 요청으로 수정한 뒤 같은 행동을 다시 해봅니다."],"question":"이 값 하나를 바꾸니 플레이할 때 무엇이 달라졌나요?","materials":["플레이 관찰 메모"],"tools":["Codex","브라우저","3주차 도구에 바뀐 규칙 기록"],"output":"변경 전후 관찰과 채택한 규칙","nextCriterion":"바꾼 이유와 실제 차이를 말하면 넘어갑니다. 기능 수를 늘리는 활동으로 바꾸지 않습니다."},{"start":105,"end":115,"duration":10,"elapsed":"105~115분","title":"작동 버전과 다음 주 할 일 저장","summary":"게임과 기획 기록을 연결해 다음 회기에 이어갑니다.","steps":["작동한 index.html 또는 프로젝트 사본을 저장하고, 주차별 도구의 ‘도구 JSON 백업’으로 현재 기획을 보관합니다.","바꾼 규칙·예상과 실제·실행 방법을 짧게 남깁니다.","오늘 만든 이미지 애셋 원본·출처·선택 이유를 따로 보관하고, 4주차에 적용·보완할 부분을 표시합니다."],"question":"다음 주 이 파일을 열면 오늘 어느 지점부터 이어갈 수 있나요?","materials":["개발노트","자산 교체 목록"],"tools":["주차별 도구: 도구 JSON 백업","게임 파일·자산 별도 저장"],"output":"작동 파일·주차별 도구 JSON·수정 이유·4주차 자산 목록","nextCriterion":"JSON은 기획 기록이고 HTML은 실행 파일임을 구별하며 정상 사본을 저장하면 넘어갑니다."},{"start":115,"end":120,"duration":5,"elapsed":"115~120분","title":"아이디어가 동작이 된 순간","summary":"오늘 만든 것과 다음 주 표현 작업을 연결합니다.","steps":["각자 자기 선택이 게임에 보인 순간을 하나 말합니다.","다음 주에는 핵심 놀이를 유지하면서 그림과 안내를 고친다고 예고합니다."],"question":"오늘 게임에서 우리 팀이 고른 생각은 어디에 남아 있나요?","materials":["다음 주 메모"],"tools":[],"output":"다음 주 개선할 화면·표현 후보","nextCriterion":"모두의 한마디를 듣고 마칩니다."}]},{"week":4,"title":"게임 화면 구성하기","date":"2026-11-27","blocks":[{"start":0,"end":10,"duration":10,"elapsed":"0~10분","title":"정상 버전을 다시 플레이하기","summary":"v0.1의 실행 여부를 먼저 보고, 정상본을 기준으로 오늘 범위를 정합니다.","steps":["W03 버전을 열어 시작→핵심 행동→완료→다시하기를 직접 해봅니다.","실행되지 않으면 직전 정상본이나 임시 도형 버전으로 돌아가 막힌 행동을 확인합니다.","정상 실행되면 무드보드와 비교해 오늘 바꿀 화면 한 부분을 고릅니다."],"question":"화면이 달라져도 계속 잘되어야 하는 동작은 무엇인가요?","materials":["W03 개발노트·무드보드·자산 목록"],"tools":["브라우저","W03 게임 파일"],"output":"유지할 동작과 오늘 개선할 화면","nextCriterion":"기존 놀이가 안 되면 이 시간 안에 정상 사본으로 복구하고 표현 범위를 줄입니다."},{"start":10,"end":25,"duration":15,"elapsed":"10~25분","title":"처음 온 친구의 화면 순서","summary":"시작·플레이·결과에서 필요한 정보를 구별합니다.","steps":["처음 온 친구가 어디를 누를지, 무엇을 할지, 끝난 뒤 어떻게 다시 할지 차례로 짚습니다.","공유 화면에서 시작·플레이·결과를 짚으며 꼭 보여줄 말과 버튼을 말하고, 웹 도구나 빈 종이에 자유롭게 메모합니다.","현재 게임에서 이미 있는 정보와 부족한 정보를 나눕니다.","아직 정상본이 없으면 복구할 한 가지를 정하고, 화면 계획은 빈 종이나 공유 화면에서 조작 안내 한 줄로 줄입니다."],"question":"처음 하는 친구는 이 화면만 보고 다음에 무엇을 해야 할까요?","materials":["실제 게임 화면·빈 종이·펜"],"tools":["4주차 화면 수정 도구"],"output":"화면별 필요한 정보 목록","nextCriterion":"시작·플레이·결과의 역할이 구별되면 넘어갑니다."},{"start":25,"end":45,"duration":20,"elapsed":"25~45분","title":"UI를 그려보고 함께 고르기","summary":"각자의 화면 제안을 비교해 팀이 채택할 배치를 정합니다.","steps":["각자 빈 종이나 공유 보드에 중요하다고 생각하는 버튼·정보·주인공 위치를 간단히 그립니다.","서로의 안에서 읽기 쉽고 놀이를 가리지 않는 부분을 말합니다.","화면 한 부분씩 합의하고 글자·버튼·이미지 위치를 확정합니다."],"question":"어떤 배치가 목표와 주인공을 가장 빨리 찾게 하나요?","materials":["빈 종이·펜 또는 공유 보드","무드보드"],"tools":["4주차 도구에 고른 화면·변화 기록"],"output":"채택한 UI 스케치와 고른 이유","nextCriterion":"전원 제안을 듣고 바꿀 위치가 표시되면 넘어갑니다."},{"start":45,"end":60,"duration":15,"elapsed":"45~60분","title":"캐릭터·배경 자산 고르고 요청하기","summary":"지난주 임시 자산을 어떤 표현으로 바꿀지 정합니다.","steps":["2주차 이미지와 3주차 자산 초안을 나란히 보고 사용할 것을 고릅니다.","주인공·목표 물건·배경이 서로 구별되는지 확인합니다.","Codex에 바꿀 화면과 자산을 특정하고, 기존 규칙·조작·완료 조건 유지를 요청합니다."],"question":"그림을 넣은 뒤에도 플레이할 때 중요한 것이 잘 보일까요?","materials":["무드보드","캐릭터·배경 이미지 또는 직접 그림","UI 스케치"],"tools":["4주차 화면 수정 웹도구","웹 도구의 Codex 요청문"],"output":"채택 자산과 화면 수정 요청","nextCriterion":"적용할 파일·위치·유지할 규칙을 팀이 확인하면 휴식합니다."},{"start":60,"end":65,"duration":5,"elapsed":"60~65분","title":"화면 수정 전에 잠깐 쉬기","summary":"기획·자산·정상본을 남겨두고 쉽니다.","steps":["수정 전 정상본을 구별해 둡니다.","5분 쉰 뒤 다시 모입니다."],"question":"돌아와서 어느 화면부터 비교해볼까요?","materials":["수정 전 화면 메모"],"tools":[],"output":"수정 전 기준 화면","nextCriterion":"5분 휴식 뒤 적용 활동을 시작합니다."},{"start":65,"end":90,"duration":25,"elapsed":"65~90분","title":"화면 한 부분씩 적용하기","summary":"바꾼 표현이 기존 놀이를 해치지 않는지 바로 확인합니다.","steps":["메인 Codex가 선택한 화면·자산을 한 부분씩 반영합니다.","청소년은 수정 전후 화면을 비교해 원하는 느낌과 읽기 쉬움을 말합니다.","시작→핵심 행동→완료→다시하기를 해보고 다음 부분을 반영합니다.","초반에 v0.1을 복구하지 못했다면 이 시간은 핵심 루프 복구에 쓰고, 새 그림·배경 적용은 미룹니다."],"question":"이번 화면 변화로 무엇을 알기 쉬워졌나요?","materials":["수정 요청","자산 원본","전후 비교 메모"],"tools":["Codex","브라우저","팀 게임 파일"],"output":"화면·자산이 반영된 작동 버전","nextCriterion":"핵심 놀이가 유지되면 넘어갑니다. 구현이 길어지면 화면 한 부분만 확정하고 효과는 미룹니다."},{"start":90,"end":105,"duration":15,"elapsed":"90~105분","title":"설명 없이 첫 플레이 보기","summary":"다른 팀 친구가 혼자 시작할 수 있는지 관찰합니다.","steps":["옆 팀에서 한 명을 초대해 제작자가 설명하지 않고 시작하게 합니다.","어디를 누르고 언제 멈추는지 관찰하고 플레이어의 말을 듣습니다.","가장 헷갈린 안내 한 가지를 팀이 고릅니다."],"question":"우리가 말해주지 않아도 친구가 알아낸 것은 무엇인가요?","materials":["첫 플레이 관찰 메모"],"tools":["브라우저","4주차 도구의 변경 뒤 확인할 행동"],"output":"처음 플레이한 친구의 행동·막힌 위치 기록","nextCriterion":"안내가 통했는지 관찰 사실을 남기면 넘어갑니다. 이 기록을 다음 주 QA에 다시 씁니다."},{"start":105,"end":115,"duration":10,"elapsed":"105~115분","title":"화면·자산·기획을 함께 저장","summary":"바뀐 화면과 아직 남은 문제를 이어갈 자료로 남깁니다.","steps":["W04 게임 사본을 저장하고 4주차 도구의 변경 내용과 유지할 선택을 확인한 뒤 ‘도구 JSON 백업’을 저장합니다.","무드보드에서 유지한 표현과 첫 플레이에서 발견한 점을 기록합니다.","소스·게임용 자산·기획 JSON을 구별해 정리합니다."],"question":"다음 주 친구들에게 꼭 시험해달라고 할 행동은 무엇인가요?","materials":["개발노트","첫 플레이 메모"],"tools":["주차별 도구: 도구 JSON 백업","게임·자산 파일 저장"],"output":"W04 실행 버전·주차별 도구 JSON·QA 후보","nextCriterion":"다음 주 테스트할 행동이 한 가지 이상 보이면 넘어갑니다."},{"start":115,"end":120,"duration":5,"elapsed":"115~120분","title":"가장 알아보기 쉬워진 것","summary":"다음 주는 기능 추가보다 친구의 플레이를 보는 시간으로 예고합니다.","steps":["각자 오늘 더 알기 쉬워진 화면을 하나 말합니다.","남은 아이디어는 다음 버전 목록에 두고 5주차 테스트로 이어갑니다."],"question":"오늘 바뀐 화면 중 친구에게 가장 도움이 될 것은 무엇인가요?","materials":["다음 버전 후보 메모"],"tools":[],"output":"팀이 채택한 UI 개선 이유","nextCriterion":"모두의 의견을 듣고 마칩니다."}]},{"week":5,"title":"게임 테스트와 완성","date":"2026-12-04","blocks":[{"start":0,"end":10,"duration":10,"elapsed":"0~10분","title":"완성 후보와 오늘 기준 확인","summary":"기능을 더하기 전에 한 판의 필수 흐름을 봅니다.","steps":["W04 게임을 실행하고 시작·행동·완료·다시하기를 짧게 확인합니다.","지난주 첫 플레이 메모와 꼭 남길 팀의 특징을 읽습니다.","오늘은 실제 문제를 찾아 고치는 날임을 정합니다."],"question":"완성했다고 말하려면 어떤 동작이 꼭 되어야 할까요?","materials":["첫 플레이 메모","기획 요약"],"tools":["브라우저"],"output":"오늘의 필수 확인 행동과 보존할 특징","nextCriterion":"새 기능 후보와 필수 수정 문제를 구별하면 넘어갑니다."},{"start":10,"end":25,"duration":15,"elapsed":"10~25분","title":"QA 기록 방법 연습하기","summary":"느낌보다 무엇을 했고 무엇이 달랐는지를 남깁니다.","steps":["한 행동의 예상 결과를 말하고 직접 해본 뒤, 웹 도구나 빈 종이에 자유롭게 적습니다.","실제 결과와 다시 해볼 순서를 웹 도구에 남깁니다.","조작·규칙·화면·재시작에서 팀이 확인할 행동 3개를 정합니다.","각 기록은 TXT로 저장하고 다음 테스트를 적습니다. 통과 기록에는 수정 요청을 보내지 않습니다."],"question":"다른 친구도 같은 문제를 보려면 어떤 순서로 해봐야 하나요?","materials":["빈 종이·포스트잇·펜"],"tools":["5주차 QA 웹도구"],"output":"팀 QA 행동 3개와 기록 예시 한 건","nextCriterion":"누가 읽어도 해볼 수 있는 순서가 있으면 넘어갑니다."},{"start":25,"end":45,"duration":20,"elapsed":"25~45분","title":"교차 플레이와 관찰","summary":"다른 팀의 설명 없는 플레이를 근거로 기록합니다.","steps":["인접 팀과 플레이어를 바꾸고 각자 짧게 해봅니다. 제작 팀은 먼저 설명하거나 대신 조작하지 않습니다.","관찰자는 막힌 순간·잘 통한 안내·예상과 다른 동작을 웹 도구나 빈 종이에 메모합니다.","플레이어는 원래 의도와 다른 동작과 더 해보고 싶은 제안을 구별해 들려줍니다."],"question":"친구가 멈춘 순간에는 실제로 어떤 일이 일어났나요?","materials":["자유 메모용 빈 종이·포스트잇·펜","각 팀 조작 안내 화면"],"tools":["5주차 QA 웹도구","브라우저","W04 실행 버전"],"output":"통과를 포함한 실제 테스트 기록 3건","nextCriterion":"문제가 없으면 통과 행동을 기록합니다. 억지 오류를 만들지 않고 다음 활동으로 갑니다."},{"start":45,"end":60,"duration":15,"elapsed":"45~60분","title":"무엇부터 고칠지 팀이 고르기","summary":"오류와 추가 아이디어를 나눈 뒤 우선순위를 정합니다.","steps":["기록을 시작·진행·종료를 막는 문제, 규칙 불일치, 표현 제안으로 나눕니다.","문제를 발견했다면 가장 먼저 고칠 한 건을 고릅니다. 모두 통과했다면 처음 온 친구의 조작·재시작을 다른 조건에서 다시 확인합니다.","필요하면 속도·배치·시간·점수 중 실제 쓰는 값 한 가지만 조정하기로 정합니다."],"question":"이 문제 하나를 먼저 고치면 어떤 플레이가 가능해지나요?","materials":["QA 기록","우선순위 표시"],"tools":["5주차 테스트 기록 도구"],"output":"수정 우선순위 한 건과 다음 버전 제안 목록","nextCriterion":"왜 먼저 고르는지 팀이 설명하면 휴식합니다. 없는 점수·시간 규칙을 새로 넣지는 않습니다."},{"start":60,"end":65,"duration":5,"elapsed":"60~65분","title":"선택한 테스트를 남겨두고 쉬기","summary":"수정할 문제 또는 통과한 행동과 정상본을 남겨두고 쉽니다.","steps":["선택한 문제 또는 다시 확인할 통과 행동과 현재 파일을 표시합니다.","5분 쉰 뒤 돌아옵니다."],"question":"돌아오면 어떤 순서로 다시 해볼까요?","materials":["선택한 QA 기록"],"tools":[],"output":"이어서 확인할 테스트 한 건","nextCriterion":"5분 휴식 뒤 수정 활동을 시작합니다."},{"start":65,"end":90,"duration":25,"elapsed":"65~90분","title":"필요한 문제 수정·통과 버전 재확인","summary":"재현 순서·예상·실제를 Codex에 전달하고 확인합니다.","steps":["문제를 발견한 경우 정상 사본을 남기고, 5주차 도구의 수정 요청문을 Codex에 전달합니다.","청소년은 수정 뒤 달라져야 할 결과를 예상하고, 고친 버전을 같은 순서로 해봅니다.","모두 통과한 경우 새 기능을 넣지 않고 처음 온 친구의 조작과 한 판·재시작을 다른 배치나 기기에서 다시 확인합니다."],"question":"고친 뒤 원래 기대한 결과가 어느 지점에서 확인되나요?","materials":["QA 기록","수정 전 정상 사본"],"tools":["Codex","브라우저","팀 게임 파일"],"output":"문제 수정본·미해결 이유 또는 통과 버전의 추가 확인","nextCriterion":"수정이 더 큰 문제를 만들면 정상본으로 복구하고 범위를 줄입니다. 활동 밖 추가 작업을 필수로 남기지 않습니다."},{"start":90,"end":105,"duration":15,"elapsed":"90~105분","title":"같은 테스트와 재시작 다시 확인","summary":"수정 한 번으로 끝내지 않고 핵심 흐름을 반복합니다.","steps":["처음 발견한 친구가 같은 순서로 다시 해봅니다.","시작→핵심 행동→완료→다시하기를 확인하고 재시작을 최소 세 번 해봅니다.","원래 규칙이 유지됐는지, 확인 못한 부분은 무엇인지 기록합니다."],"question":"다시 시작했을 때 무엇이 처음 상태로 돌아와야 하나요?","materials":["웹 도구의 수정 후 확인 메모"],"tools":["5주차 웹 도구의 수정 후 확인","브라우저"],"output":"수정 후 확인과 핵심 흐름 테스트 기록","nextCriterion":"통과·미확인·남은 문제를 구별해 기록하면 넘어갑니다."},{"start":105,"end":115,"duration":10,"elapsed":"105~115분","title":"완성 후보 저장하기","summary":"오늘 확인한 범위가 보이는 버전을 확정합니다.","steps":["W05 완성 후보와 직전 정상본을 구별해 저장합니다.","5주차 도구의 실제 결과·수정 후 확인을 갱신하고 각 테스트 TXT와 ‘도구 JSON 백업’을 저장합니다.","다음 주 배포할 버전과 남은 문제를 팀이 확인합니다."],"question":"관람객에게 자신 있게 해보라고 할 수 있는 동작은 무엇인가요?","materials":["개발노트","QA 기록"],"tools":["주차별 도구: TXT 저장·도구 JSON 백업","게임 사본 저장"],"output":"W05 완성 후보·주차별 도구 JSON·테스트 TXT","nextCriterion":"정상본과 완성 후보를 구별하고 실행 방법이 남아 있으면 넘어갑니다."},{"start":115,"end":120,"duration":5,"elapsed":"115~120분","title":"친구 덕분에 바뀐 것","summary":"개선의 이유를 다음 주 작품 설명으로 연결합니다.","steps":["각자 친구의 플레이를 보고 바뀐 점을 한 가지 말합니다.","다음 주에는 새 기능보다 실행·배포·설명에 집중한다고 예고합니다."],"question":"친구가 해본 덕분에 우리 게임은 어떻게 달라졌나요?","materials":["발표에 쓸 개선 사례 메모"],"tools":[],"output":"6주차에 설명할 개선 사례","nextCriterion":"모두의 이야기를 듣고 마칩니다."}]},{"week":6,"title":"배포하고 설명하기","date":"2026-12-11","blocks":[{"start":0,"end":10,"duration":10,"elapsed":"0~10분","title":"오늘의 최종본과 소개할 선택 확인","summary":"배포·설명에 사용할 버전을 함께 고릅니다.","steps":["W05 완성 후보와 남은 문제를 읽고 오늘 사용할 파일을 확인합니다.","일상의 소재·우리 팀 선택·친구 의견으로 바뀐 점을 한 가지씩 떠올립니다."],"question":"이 게임을 처음 보는 사람에게 꼭 들려주고 싶은 우리 선택은 무엇인가요?","materials":["W05 개발노트·QA 기록","무드보드"],"tools":["브라우저","팀 완성 후보"],"output":"최종 확인할 버전과 소개할 선택 목록","nextCriterion":"새 기능을 더하지 않고 실행·설명 범위를 합의하면 넘어갑니다."},{"start":10,"end":25,"duration":15,"elapsed":"10~25분","title":"최종 QA 한 판","summary":"배포 전에 실제 쓰는 기기에서 핵심 흐름을 확인합니다.","steps":["작품 안내만 읽고 시작→핵심 행동→완료→다시하기를 해봅니다.","남은 문제 중 시연을 막는 한 건만 확인하고 가능한 범위에서 수정합니다.","통과·미확인 항목을 구분하고 배포할 파일을 확정합니다."],"question":"관람객이 끝까지 해볼 수 있는지 지금 직접 확인한 것은 무엇인가요?","materials":["최종 QA 체크","조작 안내 초안"],"tools":["브라우저","Codex는 시연을 막는 작은 수정에만 사용"],"output":"최종 QA 기록과 확정 실행본","nextCriterion":"정상 실행되는 버전을 선택하면 넘어갑니다. 미확인을 통과로 표시하지 않습니다."},{"start":25,"end":45,"duration":20,"elapsed":"25~45분","title":"웹 실행·링크·오프라인 백업 확인","summary":"멘토의 배포 확인과 청소년의 실행·안내 준비를 함께 진행합니다.","steps":["멘토는 운영자가 정한 배포 위치에 확정본을 올리고, 청소년은 제목·조작·소개를 확인합니다.","새 창에서 게임 링크를 열어 실제 한 판을 확인하고 QR을 쓰면 연결도 해봅니다.","최종 소스·실행 파일·자산을 묶어 오프라인 백업을 만들고 로컬 실행을 확인합니다."],"question":"처음 받은 링크나 백업만으로도 게임을 시작할 수 있나요?","materials":["확정 게임 파일·자산","실행 방법 메모"],"tools":["운영자가 정한 웹 배포 환경","브라우저","QR 생성 기능은 준비된 경우 사용","로컬 실행 백업"],"output":"확인한 실행 링크 또는 QR·오프라인 백업","nextCriterion":"실제로 확인한 링크와 백업을 구별해 기록하면 넘어갑니다. 공개 접속이 안 되면 로컬 시연본을 확정하고 링크는 미확인으로 남깁니다."},{"start":45,"end":60,"duration":15,"elapsed":"45~60분","title":"작품 소개와 체험 안내 만들기","summary":"게임의 소재와 관람객이 해볼 행동을 짧게 보여줍니다.","steps":["6주차 도구에 제목·한 문장 소개·조작·출처를 정리하고, 대표 이미지는 게임 화면이나 별도 파일과 함께 공유합니다.","어떤 경험에서 시작했고 우리 팀이 고른 것과 고친 것을 한 줄씩 적습니다.","그림·소리·아이디어의 출처와 사용한 도구를 팀 기록에 연결합니다."],"question":"관람객이 이 소개만 보고 무엇을 해보면 될까요?","materials":["대표 이미지","개발노트","필요하면 자유 메모용 빈 종이·펜"],"tools":["6주차 작품 소개 웹도구","관람객에게 보여줄 공유 화면"],"output":"웹 도구에 정리한 작품 소개·체험 안내·출처 기록","nextCriterion":"관람객에게 해볼 행동과 조작이 보이면 휴식합니다."},{"start":60,"end":65,"duration":5,"elapsed":"60~65분","title":"리허설 전에 잠깐 쉬기","summary":"게임과 소개 자료를 열어두고 쉬어갑니다.","steps":["게임 실행본과 작품 소개 화면·메모를 다시 찾을 수 있게 둡니다.","5분 쉰 뒤 모입니다."],"question":"돌아와서 관람객에게 첫 문장을 어떻게 시작할까요?","materials":["작품 소개 화면·메모"],"tools":[],"output":"시연 가능한 화면과 자료","nextCriterion":"5분 휴식 뒤 3분 시연을 시작합니다."},{"start":65,"end":85,"duration":20,"elapsed":"65~85분","title":"팀별 3분 시연과 설명","summary":"4팀이 활동 시간 안에 게임과 제작 과정을 보여줍니다.","steps":["팀에서 소개·조작 시연·선택 이유·개선 사례를 맡을 역할을 정합니다.","4개 팀이 차례로 3분씩 시연합니다. 소개 1분 + 플레이·마무리 2분으로 진행하고, 우리 선택과 개선 경험을 말합니다.","팀 사이 전환과 짧은 관람객 피드백을 포함해 20분 안에 마칩니다."],"question":"게임을 보여주며 우리 팀의 선택과 바뀐 이유를 어떻게 설명할까요?","materials":["작품 소개 화면·메모","3분 시연 흐름","타이머"],"tools":["최종 실행본","브라우저 또는 로컬 실행 환경"],"output":"직접 해본 3분 시연과 개선할 안내 한 가지","nextCriterion":"4팀 모두 3분 시연을 경험하면 넘어갑니다. 활동 밖 별도 리허설을 필수로 요구하지 않습니다."},{"start":85,"end":105,"duration":20,"elapsed":"85~105분","title":"관람객 역할로 체험 동선 확인","summary":"설명 듣기와 혼자 플레이하기가 이어지는지 마지막으로 봅니다.","steps":["옆 팀이 부모·관람객 역할로 소개를 듣고 직접 게임을 시작합니다.","제작 팀은 말을 멈출 지점·조작을 넘길 지점·도움이 필요한 지점을 확인합니다.","안내 문구나 화면 한 부분만 마지막으로 고치고 같은 흐름을 다시 해봅니다."],"question":"언제 설명을 멈추고 관람객이 직접 해보게 하면 좋을까요?","materials":["관람객 체험 메모","조작 안내"],"tools":["최종 실행본","준비된 QR 또는 링크","브라우저"],"output":"체험 안내와 관람객 역할 확인 결과","nextCriterion":"소개→시작→플레이→다음 관람객 재시작 흐름을 실제로 해보면 넘어갑니다."},{"start":105,"end":115,"duration":10,"elapsed":"105~115분","title":"최종 묶음과 전시 인계 정리","summary":"활동 안에서 다음 행사에 필요한 파일을 모읍니다.","steps":["체험 뒤 게임을 수정했다면 배포본·실행 링크·오프라인 백업을 같은 최종 버전으로 갱신하고 다시 실행합니다. 최종 게임·소스·자산·실행 방법·소개를 함께 정리합니다.","6주차 도구의 작품 소개·출처·최종 선택을 확인하고 ‘도구 JSON 백업’을 저장합니다.","12/18 쇼케이스에 쓸 버전과 남은 운영 확인 사항을 담당자에게 인계할 메모로 남깁니다."],"question":"다른 사람이 이 묶음을 받으면 어떤 파일부터 열어야 하나요?","materials":["최종 인계 목록","실행 방법","작품 소개 화면·메모"],"tools":["주차별 도구: 도구 JSON 백업","최종 게임·백업 파일"],"output":"최종 파일 묶음·주차별 도구 JSON·행사 인계 메모","nextCriterion":"배포본·링크·백업의 최종 버전과 실행 방법이 일치하는지 확인하고 다음으로 넘어갑니다."},{"start":115,"end":120,"duration":5,"elapsed":"115~120분","title":"6주 동안 우리가 고른 것","summary":"처음의 경험이 게임과 설명으로 이어진 과정을 되짚습니다.","steps":["각자 가장 자랑하고 싶은 선택과 친구에게 배운 점을 한 가지 말합니다.","처음 마인드맵과 최종 화면을 함께 보고 6주 과정을 마칩니다."],"question":"처음의 우리 이야기가 게임의 어디에 남았나요?","materials":["1주차 마인드맵","최종 화면"],"tools":[],"output":"청소년 각자의 회고 한마디","nextCriterion":"모두의 이야기를 듣고 마칩니다."}]}];
