prompts.push({title:'추가 실습 · 서브에이전트로 두 관점 검토',text:'서브에이전트 2명을 사용해 아래 기획과 현재 게임을 읽기만 하며 검토해 주세요.\n\n서브에이전트 A: 청소년이 정한 핵심 행동·목표·규칙이 서로 맞는지 보고, 확인할 질문 3개를 제안해 주세요.\n서브에이전트 B: 시작·조작·성공·다시 하기를 포함한 QA 시나리오 5개를 예상 결과와 함께 제안해 주세요.\n\n두 서브에이전트는 파일을 수정하지 않습니다. 메인 에이전트가 결과를 짧게 모으고, 이번에 고칠 한 가지를 제안해 주세요. 멘토와 청소년이 선택한 뒤 메인 에이전트만 파일을 수정합니다.\n\n[기획 내용과 현재 게임 파일 전달]'});
function practicePanel(){return `<section class="section panel"><p class="eyebrow">30-MINUTE TRAINING PRACTICE</p><h3>30분 압축 실습용, 별도 스타터</h3><p>‘동네 물건 모으기’ 단일 HTML입니다. 내려받아 Codex 작업 폴더에 두고, 청소년이 고른 소재·행동·표현 한 가지를 바꿔 보세요. 시작·수집·성공·다시 하기가 준비되어 있습니다.</p><p class="mini-note">원본 8미션 기획 도구와 별개로 추가한 오리엔테이션용 예시입니다. 원본의 Phaser·Vite 공통 스타터를 대체하는 확정안이 아니며, 본 활동에는 6주간 청소년이 선택·수정하는 과정이 필요합니다.</p><div class="actions"><a class="button small" href="./starter/index.html" download="우리동네플레이어_추가실습용_스타터.html">HTML 스타터 다운로드 ↓</a><a class="button secondary small" href="./starter/index.html" target="_blank" rel="noopener noreferrer">실행해 보기 ↗</a></div><details style="margin-top:20px"><summary style="font-size:14px;font-weight:700">서브에이전트로 두 관점 검토하기</summary><p class="mini-note">A는 기획과 핵심 행동, B는 QA 시나리오를 읽기만 하며 검토합니다. 메인 에이전트가 결과를 모으고 선택한 한 가지를 수정합니다. 멘토 기록·도구의 ‘Codex 요청문’에서 예시를 복사할 수 있어요.</p><a style="font-size:12px" href="https://learn.chatgpt.com/docs/agent-configuration/subagents" target="_blank" rel="noopener noreferrer">OpenAI 공식 Subagents 안내 ↗</a></details></section>`;}
let state={data:{},qa:{},tool:'qa',recordWeek:1,submissionWeek:0,prompt:0};
let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1){state.data=cleanData(saved.data);state.qa=cleanQA(saved.qa);}}catch{storageOK=false;}
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cleanData(data){const out={};if(data&&typeof data==='object'&&!Array.isArray(data))for(const [key,value] of Object.entries(data))if(/^(plan|log)-[1-6]-(team|goal|flow|question|minimum|prepare|observed|decision|support|next)$|^qa-(issue|next)$/.test(key)&&typeof value==='string')out[key]=value.slice(0,6000);return out;}
function cleanQA(data){const out={};if(data&&typeof data==='object'&&!Array.isArray(data))for(let i=0;i<8;i++)out[i]=data[i]===true;return out;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,data:state.data,qa:state.qa,savedAt:new Date().toISOString()}));storageOK=true;}catch{storageOK=false;}document.querySelectorAll('.save-state').forEach(el=>el.textContent=storageOK?'이 기기에 저장됨':'저장 불가 · JSON 백업 사용');}
let toastTimer;function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
const KEY_VISUAL='./assets/neighborhood-keyvisual.png';
const BANNER_VISUAL='./assets/neighborhood-banner.png';
function pageKeyvisual(){return `<div class="page-keyvisual" aria-hidden="true"><img src="${BANNER_VISUAL}" alt=""><span>MENTOR STUDIO <b>우리 동네 이야기로 만드는 게임</b></span></div>`;}
function heading(kicker,title,text){return `<div class="page-head"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${text}</p></div>`;}
function home(){return `<section class="home-keyvisual"><img class="keyvisual-image" src="${KEY_VISUAL}" alt="우리동네 플레이어: 동네 공원과 도로를 배경으로 함께 모험하는 청소년"><div class="keyvisual-caption"><span>MENTOR STUDIO</span><h1>청소년의 일상에서<br>시작되는 <em>특별한 게임 개발</em></h1><p class="intro">청소년들의 동네 경험에서 시작되는<br>6주간의 게임 개발 워크숍</p><div class="actions"><a class="button" href="#week-1">6주 여정 시작하기 →</a><a class="button secondary" href="#studio">주차별 도구 열기</a></div></div></section><section class="section"><div class="section-heading"><h2>6주 여정 한눈에 보기</h2><p>목표 · 질문 · 이번 주 산출물</p></div><div class="week-grid">${weeks.map(w=>`<a class="week-card" href="#week-${w.n}"><span class="number">WEEK ${String(w.n).padStart(2,'0')}<span aria-hidden="true">↗</span></span><h3>${w.title}</h3><p>${w.tagline}</p></a>`).join('')}</div></section><section class="section"><div class="section-heading"><h2>멘토가 지킬 세 가지</h2></div><div class="principles"><div class="principle"><b>01 &nbsp; 답보다 질문</b><p>“어떤 모습이면 좋겠어?”를 먼저 건네며 청소년의 생각을 들어요.</p></div><div class="principle"><b>02 &nbsp; 한 번에 한 기능</b><p>요청하고, 실행하고, 직접 놀아 보고. 작동하는 작은 버전을 남겨요.</p></div><div class="principle"><b>03 &nbsp; 선택 이유 기억하기</b><p>청소년이 무엇을 골랐고, 왜 바꿨는지 함께 기록해요.</p></div></div></section><section class="section callout navy"><strong>생각을 모으고, 만들고, 직접 플레이하기.</strong><p>주차별 도구에 각자의 아이디어와 팀의 답을 적으면 기획서와 제작·수정 요청문으로 정리됩니다. 요청문을 Codex에 붙여 만들고, 청소년과 직접 플레이하며 다음 선택을 이어가요.</p><div class="actions"><a class="button yellow small" href="#studio">주차별 도구 열기 →</a><a class="button yellow small" href="#toolbox">멘토 기록·도구 보기 →</a></div></section>`;}
let studentQRDialog=null,studentQRTrigger=null;
function closeStudentQR(){if(studentQRDialog?.open)studentQRDialog.close();}
function openStudentQR(week,trigger){
 if(!Number.isInteger(week)||week<1||week>6)return;
 if(!studentQRDialog){
  studentQRDialog=document.createElement('dialog');
  studentQRDialog.className='student-qr-dialog';
  studentQRDialog.setAttribute('aria-labelledby','studentQRTitle');
  studentQRDialog.setAttribute('aria-describedby','studentQRDescription');
  studentQRDialog.addEventListener('cancel',event=>{event.preventDefault();closeStudentQR();});
  studentQRDialog.addEventListener('click',event=>{if(event.target!==studentQRDialog)return;const bounds=studentQRDialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)closeStudentQR();});
  studentQRDialog.addEventListener('close',()=>{document.body.classList.remove('student-qr-open');const previous=studentQRTrigger;studentQRTrigger=null;if(previous?.isConnected)previous.focus({preventScroll:true});});
  document.body.append(studentQRDialog);
 }
 if(studentQRDialog.open)return;
 const qr='./assets/student-week-'+week+'-qr.svg';
 studentQRTrigger=trigger;
 studentQRDialog.innerHTML='<div class="student-qr-dialog-heading"><div><p class="eyebrow">STUDENT TOOLS · WEEK '+String(week).padStart(2,'0')+'</p><h2 id="studentQRTitle">'+week+'주차 학생 입장 QR</h2></div><button type="button" class="button secondary small" data-action="student-qr-close" aria-label="확대된 QR코드 닫기" autofocus>닫기 ×</button></div><p id="studentQRDescription">휴대전화 카메라로 QR코드를 비추면 '+week+'주차 학생 도구가 열려요.</p><img class="student-qr-dialog-image" src="'+qr+'" width="600" height="600" alt="'+week+'주차 학생 도구 입장 QR코드"><div class="student-qr-dialog-footer"><a class="button" href="'+qr+'" download="우리동네플레이어_'+week+'주차_학생입장_QR.svg">QR 저장 ↓</a><p>이번 주 입장코드도 함께 안내해 주세요.</p></div>';
 studentQRDialog.showModal();document.body.classList.add('student-qr-open');
 studentQRDialog.querySelector('[data-action="student-qr-close"]').focus({preventScroll:true});
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action="student-qr-open"],[data-action="student-qr-close"]');if(!button)return;if(button.dataset.action==='student-qr-close')closeStudentQR();else openStudentQR(Number(button.dataset.studentWeek),button);});
window.addEventListener('hashchange',closeStudentQR);
window.addEventListener('mentor-portal-auth-change',closeStudentQR);
function studentEntryShare(n,compact=false){
 const url='https://seedcoop.github.io/uridongne-mentor-guide/student.html?week='+n;
 const qr='./assets/student-week-'+n+'-qr.svg';
 return `<aside class="student-entry-share${compact?' compact':''}" aria-label="${n}주차 학생 도구 안내"><div class="student-entry-content"><p class="eyebrow">STUDENT TOOLS · WEEK ${String(n).padStart(2,'0')}</p><h4>${compact?'학생에게 전달할 주소 · QR':'학생 도구로 활동하고 응답 제출하기'}</h4><p>주소를 전달하거나 QR을 보여 주세요. ${n}주차가 미리 선택되며, 학생은 이번 주 입장코드를 입력해요.</p><a class="student-entry-address" href="${url}" target="_blank" rel="noopener noreferrer">${url}</a><div class="actions"><button type="button" class="button small" data-action="student-link-copy" data-student-week="${n}">학생 주소 복사</button><a class="button secondary small" href="${url}" target="_blank" rel="noopener noreferrer">학생 페이지 열기 ↗</a><a class="button secondary small" href="${qr}" download="우리동네플레이어_${n}주차_학생입장_QR.svg">QR 저장 ↓</a></div></div><figure><button type="button" class="student-qr-preview" data-action="student-qr-open" data-student-week="${n}" aria-haspopup="dialog" aria-label="${n}주차 학생 입장 QR코드 크게 보기"><img src="${qr}" width="160" height="160" alt="${n}주차 학생 도구 입장 QR코드"><span aria-hidden="true">크게 보기 ↗</span></button><figcaption>${n}주차 학생 입장</figcaption></figure></aside>`;
}
function studentActivityShare(n,index){return ({1:[5],2:[1,3],3:[1,3],4:[3],5:[1,2,6],6:[3]})[n]?.includes(index)?studentEntryShare(n):'';}
function timelineDate(date){const parts=String(date||'').split('-');return parts.length===3?`${parts[0]}.${parts[1]}.${parts[2]} (금)`:date;}
function textList(value){return Array.isArray(value)?value.join(' · '):String(value||'');}
function mindmapPreview(){return `<section class="mindmap-guide"><p class="eyebrow">멘토가 화면·보드에 먼저 보여줄 틀</p><h3>우리 동네 마인드맵 활동을 위한 재료들</h3><div class="mindmap-preview"><strong class="mindmap-center">우리 동네</strong><div class="mindmap-branches"><div><b>자주 가는 곳</b><small>어디에 자주 가나요?</small></div><div><b>만나는 사람</b><small>누구와 마주치나요?</small></div><div><b>기억나는 일</b><small>무슨 일이 있었나요?</small></div><div><b>좋아하는 놀이</b><small>무엇을 하며 노나요?</small></div></div></div><p class="mindmap-hint"><strong>준비 재료</strong> 큰 종이·포스트잇·펜·색연필. 멘토는 중앙 ‘우리 동네’와 네 키워드를 화면이나 보드에 미리 표시하고, 경험 하나가 가지로 이어지는 모습을 보여줘요.</p><p class="mindmap-hint">청소년이 큰 종이에 직접 그리거나 포스트잇을 붙여 함께 시작해요. 네 가지를 모두 채울 필요는 없어요. 떠오르는 가지부터 낱말·그림 2개 이상을 남기고, 고른 소재에 별표와 행동 낱말 하나를 붙여요.</p></section>`;}
function moodboardCTA(){return `<aside class="studio-cta mb-timeline-cta"><div><strong>그림과 색을 한 장에 모아요</strong><p>35분 안내 · 색 3~6개 · 임시 상징 · 참고 그림 3개와 이유·출처 · 피할 표현 3~5개</p></div><div class="actions"><a class="button" href="#moodboard">시각 무드보드 만들기 →</a><a class="button secondary small" href="#studio/2">게임 타이틀 요청문 정리 →</a><a class="button secondary small" href="./worksheets/game-moodboard-template.pptx" download="우리팀_게임무드보드_템플릿.pptx">빈 PPT 양식 ↓</a><a class="button secondary small" href="./worksheets/game-moodboard-template.pdf" download="우리팀_게임무드보드_템플릿.pdf">빈 PDF 양식 ↓</a></div></aside>`;}
function timelineSection(n){const week=weeklyTimeline.find(x=>x.week===n);if(!week)return '';return `<section class="timeline-section" aria-labelledby="timelineHeading"><div class="timeline-heading"><div><p class="eyebrow">WEEK ${String(n).padStart(2,'0')} · 120 MINUTES</p><h2 id="timelineHeading">운영 타임라인 <span>러프안</span></h2><p class="timeline-session"><b>${esc(timelineDate(week.date))}</b><span>휴식 포함 총 120분</span></p></div><div class="timeline-actions no-print"><button class="button secondary small" data-action="timeline-expand">모두 펼치기</button><button class="button secondary small" data-action="timeline-collapse">모두 접기</button><button class="button small" data-action="timeline-print">타임라인 인쇄</button></div></div><p class="timeline-source">${n===1?'개별 기획서 → 팀 회의·발표 → 투표 → 대표 기획 정리 · 휴식 포함 120분':'구성 근거: 프로그램 기획 4쪽 · 운영 계획안 3–5쪽. 세부 시간 배분과 진행 순서는 운영 러프안입니다.'}</p><div class="operation-timeline">${week.blocks.map((block,i)=>`<details class="timeline-block${/휴식|쉬기/.test(block.title)?' break-block':''}" data-duration="${block.duration}" data-start="${block.start}" data-end="${block.end}"><summary><span class="timeline-clock"><strong>${block.duration}분</strong><span>누적 ${block.end}분</span></span><span class="timeline-brief"><span class="timeline-activity-title"><span class="activity-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(block.title)}</strong></span><span class="timeline-task">${esc(block.summary)}</span></span><span class="timeline-chevron" aria-hidden="true"></span></summary><div class="timeline-body"><div class="timeline-procedure"><h3>이렇게 진행해요</h3><ol>${block.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></div><dl class="timeline-detail"><div><dt>멘토 질문</dt><dd>${esc(block.question)}</dd></div><div><dt>자료 · 도구</dt><dd>${esc([...block.materials,...block.tools].join(' · '))}</dd></div></dl>${n===1&&i===2?mindmapPreview():''}${n===1&&i===5?window.WorkshopTools.cta(1):''}${n===2&&i===1?moodboardCTA():''}${n===2&&i===3?window.WorkshopTools.cta(2):''}${n===3&&(i===1||i===3)?window.WorkshopTools.cta(3):''}${block.note?`<p class="mini-note">${esc(block.note)}</p>`:''}${studentActivityShare(n,i)}<div class="timeline-result"><strong>끝날 때 남길 것</strong><p>${esc(textList(block.output))}</p></div></div></details>`).join('')}</div></section>`;}
function originalToolReference(w){if(!w.links.length)return '';return `<details class="optional-tool-reference"><summary>원본 8미션 기획 도구 · 선택 참고</summary><p>더 자세한 기획 질문이 필요할 때 참고해요. 이번 주 활동은 위 주차별 도구로 진행할 수 있어요.</p><div class="actions">${w.links.map(step=>`<a class="button secondary small" href="${TOOL}#mission-${step}" target="_blank" rel="noopener noreferrer">원본 미션 ${step} 참고 ↗</a>`).join('')}</div><p class="mini-note">원본은 ‘아이디어 파일 저장’과 ‘저장한 아이디어 열기’를 사용해요. 주차별 도구의 JSON과는 별도 파일입니다.</p></details>`;}
function recoveryBranch(n){return n===4?'<aside class="recovery-branch"><strong>v0.1이 실행되지 않는 팀</strong><p>초반 25분은 정상본·임시 도형 버전 복구를 먼저 해요. 복구되면 안내 한 가지만 개선하고, 계속 막히면 65~90분 구현 시간도 핵심 루프 복구에 써요. 새 그림·배경은 미루고 화면 계획은 조작 안내 한 줄로 줄여요.</p></aside>':'';}
function unreleasedWeekView(n,content){
 const boundary=content.indexOf('</nav>')+6;
 return content.slice(0,boundary)+`<div class="week-title"><div><p class="eyebrow">WEEK ${String(n).padStart(2,'0')}</p><h1>${esc(weeks[n-1].title)}</h1></div></div><section class="week-release" aria-label="${n}주차 과정 공개 예정"><div class="week-release-content" inert aria-hidden="true">${content.slice(boundary)}</div><div class="week-release-notice" role="status"><p class="eyebrow">COMING SOON</p><h2>${n}주차 과정은 공개 예정이에요</h2><p>활동 시기에 맞춰 자세한 운영 내용을 안내할게요.<br>지금은 1~3주차 과정을 먼저 준비해 주세요.</p><a class="button secondary small" href="#week-3">3주차 과정 보기</a></div></section>`;
}
function weekView(n){const w=weeks[n-1];const content=`<nav class="week-tabs" aria-label="주차 선택">${weeks.map(x=>`<a href="#week-${x.n}" ${x.n===n?'aria-current="page"':''}><b>${x.n}주차</b>${x.short}</a>`).join('')}</nav><div class="week-title"><div><p class="eyebrow">WEEK ${String(n).padStart(2,'0')} · ${w.tagline}</p><h1>${w.title}</h1><p class="week-goal"><span class="goal-pill">오늘의 목표</span><span class="week-goal-text">${w.goal}</span></p></div><div class="duration"><strong>120분</strong>운영 러프안</div></div><div class="two-columns week-support"><section class="panel"><h3>청소년이 결정할 것</h3><p class="question">${w.question}</p><div class="decision"><small>DECISION</small><p>${w.decision}</p></div><h4>멘토의 지원</h4><p>${w.mentor}</p></section><section class="panel"><h3>멘토가 준비할 것</h3><p>${w.minimum}</p><h4>미리 챙기기</h4><div class="check-items">${w.materials.map(m=>`<span>${m}</span>`).join('')}</div>${studentEntryShare(n,true)}</section></div><section class="section"><div class="section-heading"><h2>교육과 활동 범위</h2><p>${n===1?'개별 기획을 먼저 기록하고 투표 뒤 대표 기획을 저장해요.':'주차별 도구에 오늘의 결정을 정리해요.'}</p></div><div class="tool-scope"><div class="scope-box today"><b>오늘 열기</b><p>${w.open}</p></div><div class="scope-box"><b>다음으로 미루기</b><p>${w.defer}</p></div></div><div class="actions"><a class="button small" href="#toolbox/${n}">활동계획·일지 작성 →</a><button class="button secondary small" data-action="print">주차 가이드 인쇄</button></div><p class="mini-note">${n===1?'개인 기획서는 MD 또는 PDF로 각각 보관합니다. 가상의 게임 타이틀 커버는 도구의 요청문을 Codex에 전달해 생성합니다. 투표 뒤 선정된 기획을 팀 대표 기록으로 저장하고, 다음 주에는 그 기획을 이어받습니다.':'주차별 도구의 ‘도구 JSON 백업’으로 입력을 보관하고, 다른 기기에서는 ‘도구 기록 불러오기’로 이어가요. 게임 파일은 별도로 저장해요.'}</p>${originalToolReference(w)}</section>${recoveryBranch(n)}${n===2?moodboardCTA():n!==1?window.WorkshopTools.cta(n):''}${timelineSection(n)}<section class="section panel details-list"><h3>막히는 순간, 이렇게 이어 가요</h3>${w.stuck.map(s=>`<details><summary>${s[0]}</summary><p>${s[1]}</p></details>`).join('')}</section><div class="next-week">${n>1?`<a class="button secondary" href="#week-${n-1}">← ${n-1}주차</a>`:'<a class="button secondary" href="#home">← 처음으로</a>'}${n<6?`<a class="button" href="#week-${n+1}">${n+1}주차 살펴보기 →</a>`:'<a class="button" href="#toolbox">멘토 기록·도구 →</a>'}</div>`;return window.MentorPortal?.shouldBlurGuideWeek(n)?unreleasedWeekView(n,content):content;}

const tabs=[['qa','QA 체크'],['prompts','Codex 요청문']];
function field(id,label,placeholder,type='textarea',full=false){const val=state.data[id]||'';return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label>${type==='input'?`<input id="${id}" data-record="${id}" value="${esc(val)}" placeholder="${esc(placeholder)}" maxlength="6000" autocomplete="off">`:`<textarea id="${id}" data-record="${id}" placeholder="${esc(placeholder)}" maxlength="6000">${esc(val)}</textarea>`}</div>`;}
const checks=[['시작하기','처음 실행한 사람이 안내를 보고 시작한다.'],['핵심 조작','정한 키·마우스·화면 버튼으로 주요 행동을 한다.'],['규칙과 상태 변화','점수·개수·표시가 팀이 정한 규칙과 일치한다.'],['성공 또는 종료','조건을 만족하면 결과로 이어진다.'],['다시 하기','점수·시간·위치·물건이 처음 상태로 돌아온다.'],['화면과 안내','글자가 읽히고 중요한 버튼·목표물이 보인다.'],['다른 기기에서 실행','전달할 실행본과 안내로 직접 열어 본다.'],['표현과 출처','청소년이 고른 특징이 남고 사용 자산의 출처가 있다.']];
function qa(){return `<h3>최종 QA 체크 <span class="save-state">${storageOK?'이 기기에 저장됨':'저장 불가 · JSON 백업 사용'}</span></h3><p class="form-note">친구는 플레이, 제작자는 관찰. 체크는 직접 확인한 뒤에 해요. 현재 기록은 최종 후보 한 버전 기준입니다.</p><div class="qa-list">${checks.map((c,i)=>`<label class="qa-item"><input type="checkbox" data-qa="${i}" ${state.qa[i]?'checked':''}><span><b>${c[0]}</b><small>${c[1]}</small></span></label>`).join('')}</div><div class="form-grid">${field('qa-issue','오류 기록 · 한 건씩 줄을 나누어 적기','버전 / 재현 순서 / 예상 / 실제 / 우선순위 / 해결 여부\n예: v0.2 / 결과→다시 하기 / 점수 0 / 점수 30 유지 / 규칙 오류 / 미해결')}${field('qa-next','수정 후 재검사 · 다음 버전으로 남길 것','어떤 조건으로 다시 확인했는지 / 유지할 재미 / 다음에 바꿀 것')}</div><p class="mini-note">우선순위: 진행 불가 → 규칙 오류 → 표현 개선. 수정한 곳 외에 시작·종료·다시 하기도 다시 확인하세요.</p><div class="actions"><button class="button small" data-action="print">QA 기록 인쇄 · PDF 저장</button></div>`;}
function promptPane(){return `<h3>Codex에 건넬 짧은 요청문</h3><p class="form-note">대괄호를 팀의 결정으로 바꿔 붙여 넣으세요. 전체 제작 프롬프트보다 오늘 할 범위를 먼저 전달합니다.</p><label for="promptSelect" class="mini-note">요청할 작업</label><br><select id="promptSelect" class="prompt-select">${prompts.map((p,i)=>`<option value="${i}" ${state.prompt===i?'selected':''}>${p.title}</option>`).join('')}</select><pre class="prompt-box" id="promptText" tabindex="0">${esc(prompts[state.prompt].text)}</pre><div class="actions"><button class="button small" data-action="copy">요청문 복사</button><button class="button secondary small" data-action="prompt-download">TXT 저장</button></div><p class="advanced-procedure">검토를 나눠 맡긴 뒤에는 활동 열기 → 검토 결과 읽기 → 채택 의견을 메인에 전달해요.</p><div class="callout" style="margin-top:24px"><strong>요청 → 생성 → 실행 → 청소년의 확인 → 한 가지 수정</strong><p>AI가 제시한 결과를 그대로 정답으로 두지 않습니다. “우리 규칙과 같은가?”를 청소년이 플레이하며 확인해요.</p></div>`;}
function qaStorage(){return `<div class="qa-storage"><small>QA 기록은 이 기기에 자동 저장됩니다.</small><div class="actions"><button class="button secondary small" data-action="backup">QA 백업</button><button class="button secondary small" data-action="restore">QA 불러오기</button></div></div>`;}
function toolbox(){return `${heading('MENTOR RECORDS','활동계획과 멘토 교육일지','이번 주 계획을 준비하고, 실제 활동 진행과 청소년의 선택을 기록해요.')}<div id="mentorPortal" data-portal-view="home" data-week="${state.submissionWeek||0}"></div><section class="section mentor-reference" aria-labelledby="referenceHeading"><div class="section-heading"><div><p class="eyebrow">MAKING REFERENCE</p><h2 id="referenceHeading">게임 제작 참고</h2></div><p>QA를 확인하고 Codex 요청문을 꺼내 써요.</p></div><div class="tool-tabs" role="tablist" aria-label="게임 제작 참고">${tabs.map(([id,label])=>`<button role="tab" id="tab-${id}" data-tool="${id}" aria-controls="toolPane" aria-selected="${state.tool===id}" tabindex="${state.tool===id?'0':'-1'}">${label}</button>`).join('')}</div><section class="panel tool-pane" id="toolPane" role="tabpanel" aria-labelledby="tab-${state.tool}">${state.tool==='prompts'?promptPane():qa()}${state.tool==='qa'?qaStorage():''}</section></section>`;}
let renderSequence=0;
function protectedRoute(hash){return /^#week-[1-6]$/.test(hash)||/^#studio(?:\/[1-6])?$/.test(hash)||/^#moodboard(?:\/2)?$/.test(hash)||hash.startsWith('#toolbox');}
function pageChrome(kind,match,focus){
 document.body.dataset.view=kind;
 if(kind!=='home')$('main').insertAdjacentHTML('afterbegin',pageKeyvisual());
 document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===kind||(kind==='moodboard'&&a.dataset.nav==='studio');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.title=kind==='moodboard'?'시각 무드보드 | 멘토의 6주 노트':kind==='week'?match[1]+'주차 · '+weeks[+match[1]-1].title+' | 멘토의 6주 노트':kind==='studio'?'주차별 도구 | 멘토의 6주 노트':kind==='toolbox'?'활동계획과 교육일지 제출 | 멘토의 6주 노트':'우리동네 플레이어 · 멘토의 6주 노트';
 if(focus){window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}
}
async function render(focus=false){
 const sequence=++renderSequence;
 let hash=location.hash||'#home';
 if(hash==='#toolbox/mapping'){hash='#toolbox';history.replaceState(null,'',hash);}
 const match=hash.match(/^#week-([1-6])$/);
 const kind=match?'week':/^#studio(?:\/[1-6])?$/.test(hash)?'studio':/^#moodboard(?:\/2)?$/.test(hash)?'moodboard':hash.startsWith('#toolbox')||['#records','#admin','#account'].includes(hash)?'toolbox':'home';
 const needsAccess=protectedRoute(hash);
 if(!needsAccess)window.MentorPortal?.leaveGuide(hash==='#account');
 if(needsAccess){
  // Replace the previous view before awaiting authentication: no detail flash,
  // including when navigation or an expired session interrupts another request.
  $('main').innerHTML='<div id="mentorPortal" data-portal-view="guide"></div>';
  pageChrome(kind,match,focus);
  if(!window.MentorPortal?.requireAccess){$('mentorPortal').textContent='로그인 연결을 불러오지 못했습니다. 페이지를 새로고침해 주세요.';return;}
  const allowed=await window.MentorPortal.requireAccess(hash);
  if(sequence!==renderSequence||(location.hash||'#home')!==hash||!allowed)return;
 }
 if(kind==='week')$('main').innerHTML=weekView(+match[1]);
 else if(kind==='studio')$('main').innerHTML=window.WorkshopTools.render(Number(hash.split('/')[1])||0);
 else if(kind==='moodboard')$('main').innerHTML=window.VisualMoodboard.render();
 else if(['#records','#admin','#account'].includes(hash))$('main').innerHTML='<div id="mentorPortal" data-portal-view="'+hash.slice(1)+'" data-week="0"></div>';
 else if(kind==='toolbox'){
  const sub=hash.split('/')[1];
  if(/^[1-6]$/.test(sub||'')){state.recordWeek=+sub;state.submissionWeek=+sub;state.tool='qa';}
  else if(sub==='plan'||sub==='log')state.tool='qa';
  else if(tabs.some(t=>t[0]===sub))state.tool=sub;
  else state.tool='qa';
  $('main').innerHTML=toolbox();
 }else $('main').innerHTML=home();
 if((kind==='week'&&Number(match[1])===3)||(hash.startsWith('#toolbox')&&state.tool==='prompts'))$('main').insertAdjacentHTML('beforeend',practicePanel());
 pageChrome(kind,match,focus);
 if(!needsAccess||document.getElementById('mentorPortal'))window.MentorPortal?.mount();
}
async function copy(){const txt=prompts[state.prompt].text;let ok=false;try{await navigator.clipboard.writeText(txt);ok=true;}catch{const ta=document.createElement('textarea');ta.value=txt;ta.style.cssText='position:fixed;left:-9999px';document.body.append(ta);ta.select();try{ok=document.execCommand('copy');}catch{}ta.remove();}if(ok)toast('요청문을 복사했어요. 대괄호를 팀의 내용으로 바꿔 주세요.');else{const range=document.createRange();range.selectNodeContents($('promptText'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);toast('선택된 요청문을 직접 복사하거나 TXT로 저장해 주세요.');}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tool]');if(tab){state.tool=tab.dataset.tool;history.replaceState(null,'',`#toolbox/${state.tool}`);render().then(()=>$(`tab-${state.tool}`)?.focus());return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='timeline-expand'||action==='timeline-collapse'){document.querySelectorAll('.timeline-block').forEach(block=>block.open=action==='timeline-expand');}if(action==='timeline-print'){document.body.classList.add('print-timeline');window.print();}if(action==='print')window.print();if(action==='copy')copy();if(action==='prompt-download')download(prompts[state.prompt].text,`우리동네플레이어_${prompts[state.prompt].title.replace(/[·\s]+/g,'_')}.txt`);if(action==='backup'){save();const data=Object.fromEntries(Object.entries(state.data).filter(([key])=>/^qa-/.test(key)));download(JSON.stringify({format:'uridongne-mentor-qa-backup',version:1,exportedAt:new Date().toISOString(),data,qa:state.qa},null,2),'우리동네플레이어_QA_백업.json','application/json;charset=utf-8');toast('QA 기록을 백업했어요.');}if(action==='restore')$('restoreFile').click();});
document.addEventListener('input',e=>{if(e.target.dataset.record){state.data[e.target.dataset.record]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.dataset.qa!==undefined){state.qa[e.target.dataset.qa]=e.target.checked;save();}if(e.target.id==='promptSelect'){state.prompt=Number(e.target.value);$('promptText').textContent=prompts[state.prompt].text;}});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-tool]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let idx=tabs.findIndex(t=>t[0]===tab.dataset.tool);idx=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;document.querySelector(`[data-tool="${tabs[idx][0]}"]`).click();});
$('restoreFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('1MB 이하 QA 백업 파일을 선택해 주세요.');const imported=JSON.parse(await file.text());if(!['uridongne-mentor-qa-backup','uridongne-mentor-guide-backup'].includes(imported.format)||imported.version!==1||!imported.data||typeof imported.data!=='object'||Array.isArray(imported.data))throw new Error('이 도구에서 백업한 QA 파일을 선택해 주세요.');if((state.data['qa-issue']||state.data['qa-next']||Object.values(state.qa).some(Boolean))&&!window.confirm('현재 QA 기록을 백업 내용으로 바꿀까요?'))return;const incoming=cleanData(imported.data);state.data['qa-issue']=incoming['qa-issue']||'';state.data['qa-next']=incoming['qa-next']||'';state.qa=cleanQA(imported.qa);save();state.tool='qa';await render();toast('QA 기록을 불러왔어요.');}catch(err){toast(err instanceof SyntaxError?'JSON을 읽지 못했어요. QA 백업 파일을 확인해 주세요.':err.message);}finally{e.target.value='';}});
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action="student-link-copy"]');if(!button)return;
 const week=Number(button.dataset.studentWeek);if(!Number.isInteger(week)||week<1||week>6)return;
 const url='https://seedcoop.github.io/uridongne-mentor-guide/student.html?week='+week;
 let copied=false;try{await navigator.clipboard.writeText(url);copied=true;}catch{const input=document.createElement('textarea');input.value=url;input.style.cssText='position:fixed;left:-9999px';document.body.append(input);input.select();try{copied=document.execCommand('copy');}catch{}input.remove();}
 toast(copied?week+'주차 학생 주소를 복사했어요. 이번 주 입장코드도 함께 안내해 주세요.':'주소를 복사하지 못했어요. 학생 페이지를 열어 주소를 직접 복사해 주세요.');
});
window.addEventListener('hashchange',()=>render(true));
window.addEventListener('mentor-portal-auth-change',()=>render());
function recheckDetails(){if(!document.hidden&&protectedRoute(location.hash))window.MentorPortal?.revalidateAccess();}
window.addEventListener('focus',recheckDetails);
window.addEventListener('pageshow',recheckDetails);
document.addEventListener('visibilitychange',recheckDetails);
setInterval(recheckDetails,60000);
window.addEventListener('pagehide',save);
let timelinePrintState=[];
window.addEventListener('beforeprint',()=>{if(!timelinePrintState.length)timelinePrintState=[...document.querySelectorAll('.timeline-block')].map(block=>({block,open:block.open}));timelinePrintState.forEach(({block})=>block.open=true);document.querySelectorAll('.print-value').forEach(e=>e.remove());document.querySelectorAll('.field input,.field textarea,.field select').forEach(el=>{const text=document.createElement('div');text.className='print-value';text.textContent=el.tagName==='SELECT'?el.selectedOptions[0].textContent:(el.value||' ');el.insertAdjacentElement('afterend',text);});});
window.addEventListener('afterprint',()=>{document.querySelectorAll('.print-value').forEach(e=>e.remove());timelinePrintState.forEach(({block,open})=>{if(block.isConnected)block.open=open;});timelinePrintState=[];document.body.classList.remove('print-timeline');});
render();

window.MentorGuidePlanSeed=n=>{if(!window.MentorPortal?.hasAuthenticatedSession())return {};const w=weeks[n-1],t=weeklyTimeline.find(x=>x.week===n);return w?{goal:w.goal,flow:t.blocks.map(b=>b.title+" · "+b.duration+"분\n"+b.summary).join("\n\n"),question:w.question+"\n"+w.mentor,materials:w.materials.join(" · "),completion:w.minimum}:{};};
